corrected_code:
const express = require('express');
const router = express.Router();
const { WebPushSubscription, AccountMember } = require('../models');

router.post('/api/webpush/subscribe', verifyUserAuth, async (req, res) => {
  const { accountId, subscription } = req.body;

  const member = await AccountMember.findOne({
    where: { accountId, userId: req.user.id }
  });
  if (!member) {
    return res.status(403).json({ error: 'Forbidden: you are not a member of the target account' });
  }

  const created = await WebPushSubscription.upsert({
    accountId,
    userId: req.user.id,
    endpoint: subscription.endpoint,
    p256dh: subscription.keys.p256dh,
    auth: subscription.keys.auth,
    createdAt: new Date()
  });

  return res.json({ success: true, accountId });
});
